// Configuración centralizada de Seguimiento
return [{ json: {
  CHATWOOT_URL: 'https://chatwoot.xtract.app',
  CHATWOOT_ACCOUNT_ID: '1',
  WA_SHEET_URL: 'https://docs.google.com/spreadsheets/d/1w6wVAuYmHjI8Fk4b3S1VLxAcgSSQkUjHOTrE1enmaP8/edit',
  WA_SEGUIMIENTO_ESPERA_MIN: 180, // 3 horas
  WA_SEGUIMIENTO_NAME: 'reactivacion_closed_lost_seguimiento',
  WA_SEGUIMIENTO_LANG: 'es_AR',
  WA_SEGUIMIENTO_PREVIEW: 'Nos juntamos hace un tiempo cuando en {{1}} estaban buscando automatizar el ingreso de facturas en {{2}}. Quería saber cómo vienen con ese proceso, si ya encontraron alguna forma de automatizarlo o si lo siguen haciendo de forma manual.'
} }];

// ---------------------------------------------------------------------
// SANEO DE LOS DOS PARAMETROS QUE VE EL CLIENTE.
// La plantilla aprobada por Meta es fija y tiene DOS huecos:
//   "...cuando en {1} estaban buscando automatizar el ingreso de
//    facturas en {2}."
// No se pueden sacar clausulas en runtime, asi que cada hueco tiene que
// recibir algo que lea bien SIEMPRE. Ante la duda, generico.
// ---------------------------------------------------------------------
const norm = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/\s+/g,' ').trim();

// Nombres propios de ERP con su grafia correcta. La hoja los trae en
// cualquier capitalizacion ('sap ecc', 'siigo') y sale tal cual al cliente.
const ERP = {
  'sap ecc':'SAP ECC','sap b1':'SAP B1','sap business one':'SAP Business One',
  'siigo':'Siigo','siigo nube':'Siigo Nube','siigo pyme':'Siigo Pyme',
  'odoo 17':'Odoo 17','odoo':'Odoo','tango':'Tango','tango delta 5':'Tango Delta 5',
  'softland':'Softland','sage50':'Sage 50','alegra':'Alegra','colppy':'Colppy',
  'contagram':'Contagram','helisa':'Helisa','gecom':'GECOM','versat':'VERSAT',
  'world office':'World Office','infor lx':'Infor LX','oracle':'Oracle',
  'finnegans go':'Finnegans GO','autologica':'Autológica','kipin':'Kipin',
  'ijserver':'IJServer','rojo soft':'Rojo Soft','sag':'SAG','calden oil':'Calden Oil'
};

// Un valor NO sirve como nombre de sistema si es generico, es una anotacion
// del CRM, o directamente dice que no tienen sistema.
function sistemaUsable(raw){
  const n = norm(raw);
  if (!n) return false;
  if (/^(otro|otros|ninguno|ninguna|n\/?a|na|-|--|si|no)$/.test(n)) return false;
  if (/sin sistema|no tiene|no usan|terceriz|manual|excel|papel|cuaderno/.test(n)) return false;
  if (/propio|a medida|desarrollo|plataforma|generico/.test(n)) return false;
  if (/[-:;,()]|\by\b/.test(String(raw))) return false;   // anotacion, no un nombre
  if (n.split(' ').length > 3) return false;              // frase, no un nombre
  if (n.length > 22) return false;
  return true;
}

function limpiarSistema(raw){
  if (!sistemaUsable(raw)) return 'su sistema';
  const n = norm(raw);
  if (ERP[n]) return ERP[n];
  return String(raw).trim().replace(/\b[a-záéíóúñ]/g, (c) => c.toUpperCase());
}

// 'empresa' solo se usa si es DISTINTA del nombre del contacto. En la hoja
// 23 de 53 filas repiten el nombre de la persona en la columna empresa, y
// asi salio "cuando en Luis Rodriguez estaban buscando". Se pierde algo de
// personalizacion en las pocas donde la empresa se llama igual que el
// contacto, y a cambio no sale nunca una frase absurda.
function limpiarEmpresa(rawEmpresa, rawNombre){
  const e = String(rawEmpresa == null ? '' : rawEmpresa).trim();
  if (!e) return 'su empresa';
  if (norm(e) === norm(rawNombre)) return 'su empresa';
  return e;
}

// Filtrar leads que ya cumplieron las 2hs y no tienen seguimiento enviado ni respondido
const cfg = $('Config').first().json;
const esperaMs = (cfg.WA_SEGUIMIENTO_ESPERA_MIN || 120) * 60 * 1000;
const ahora = Date.now();
const MAX_ANTIGUEDAD_MS = 7 * 24 * 60 * 60 * 1000; // 7 días max para cubrir fines de semana

const elegibles = [];
for (const item of $input.all()) {
  const row = item.json || {};
  const estado = String(row.estado || "").toLowerCase().trim();
  const convId = row.chatwoot_conversation_id;
  const seg = String(row.seguimiento || "").toLowerCase().trim();
  const fechaEnvioStr = row.fecha_envio;

  // Solo enviados con conversación
  if (estado !== "enviado" || !convId) continue;
  // Si ya se mandó seguimiento o ya respondió o cancelado, saltear
  if (seg === "enviado" || seg === "respondio" || seg === "cancelado") continue;
  if (!fechaEnvioStr) continue;

  const fechaEnvio = new Date(fechaEnvioStr).getTime();
  if (isNaN(fechaEnvio)) continue;

  // =====================================================================
  // PISO: SOLO LA TANDA DE HOY.
  //
  // Antes la unica cota era MAX_ANTIGUEDAD (7 dias), y eso arrastraba
  // leads viejos en cada corrida. Liliana Graciano (enviada el 25/08)
  // recibio el seguimiento TRES veces: seguia entrando en el rango
  // mientras 'Marcar seguimiento enviado' fallaba y nunca la sacaba de
  // la lista de pendientes.
  //
  // Con el piso en la medianoche de hoy, una corrida solo puede tocar
  // leads de la tanda del dia. Si manana hay que recuperar a alguien
  // viejo, se hace a mano o se vacia su celda 'seguimiento' -- pero el
  // cron no puede volver atras solo.
  // =====================================================================
  const inicioDeHoy = new Date();
  inicioDeHoy.setHours(0, 0, 0, 0);
  if (fechaEnvio < inicioDeHoy.getTime()) continue;

  const antiguedad = ahora - fechaEnvio;
  // Ventana: entre esperaMs (2hs) y 7 días
  if (antiguedad >= esperaMs && antiguedad <= MAX_ANTIGUEDAD_MS) {

    elegibles.push({ json: {
      row_number: row.row_number,
      telefono: row.telefono,
      nombre: row.nombre,
      primer_nombre: row.primer_nombre || row.nombre,
      empresa: limpiarEmpresa(row.empresa, row.nombre),
      sistema: limpiarSistema(row.sistema),
      conversation_id: convId,
      fecha_envio: row.fecha_envio,
      owner: "Nicolás González"
    } });
  }
}

return elegibles;

